INSERT INTO lr_questions (section_id, qid, preptest, section, question_number, question_type, stimulus, prompt, correct_choice, is_explained, source_note) SELECT s.id, $batch13$PT144-S4-Q15$batch13$, 144, 4, 15, $batch13$Flaw$batch13$, $batch13$Armstrong: For the treatment of a particular disease, Dr. Sullivan argues for using nutritional supplements rather than the pharmaceuticals that most doctors prescribe. But this is in his self-interest since he is paid to endorse a line of nutritional supplements. Thus, we should not use nutritional supplements in treating the disease.$batch13$, $batch13$Armstrong’s argument is flawed in that it$batch13$, $batch13$D$batch13$, true, $batch13$Batch 13; question text from local bank.$batch13$ FROM lr_sections s WHERE s.preptest=144 AND s.section=4 AND NOT EXISTS (SELECT 1 FROM lr_questions q WHERE q.qid=$batch13$PT144-S4-Q15$batch13$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch13$A$batch13$, $batch13$relies on two different meanings of the term “supplement” to draw a conclusion$batch13$, $batch13$Irrelevant$batch13$, false FROM lr_questions q WHERE q.qid=$batch13$PT144-S4-Q15$batch13$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch13$A$batch13$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch13$B$batch13$, $batch13$relies solely on an appeal to an authority whose trustworthiness should not necessarily be taken for granted$batch13$, $batch13$Opposite$batch13$, false FROM lr_questions q WHERE q.qid=$batch13$PT144-S4-Q15$batch13$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch13$B$batch13$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch13$C$batch13$, $batch13$appeals to people’s emotions regarding the treatment of disease rather than to the efficacy of the two approaches to treatment$batch13$, $batch13$Irrelevant$batch13$, false FROM lr_questions q WHERE q.qid=$batch13$PT144-S4-Q15$batch13$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch13$C$batch13$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch13$D$batch13$, $batch13$criticizes Dr. Sullivan’s motives for holding a position rather than addressing the position itself$batch13$, $batch13$Correct$batch13$, true FROM lr_questions q WHERE q.qid=$batch13$PT144-S4-Q15$batch13$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch13$D$batch13$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch13$E$batch13$, $batch13$fails to justify its presumption that nutritional supplements cannot be used in conjunction with other treatments$batch13$, $batch13$Irrelevant$batch13$, false FROM lr_questions q WHERE q.qid=$batch13$PT144-S4-Q15$batch13$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch13$E$batch13$) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanations (question_id, style) SELECT q.id, 'single' FROM lr_questions q WHERE q.qid=$batch13$PT144-S4-Q15$batch13$ AND NOT EXISTS (SELECT 1 FROM lr_explanations e WHERE e.question_id=q.id AND e.style IN ('single','standard')) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_steps (explanation_id, position, label, body) SELECT e.id, v.position, v.label, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES (0, $batch13$Conclusion$batch13$, $batch13$We shouldn't use nutritional supplements to treat the disease.$batch13$), (1, $batch13$Evidence$batch13$, $batch13$Dr. Sullivan, who favors supplements, is paid to endorse a line of them.$batch13$), (2, $batch13$Evaluate$batch13$, $batch13$Armstrong attacks Sullivan's motive instead of the evidence for supplements. Even a paid endorser can be right. At most, Armstrong gives a reason to check the claim, not a reason to reject supplements.$batch13$), (3, $batch13$Goal$batch13$, $batch13$It attacks the person's motive instead of the position.$batch13$)) v(position,label,body) WHERE q.qid=$batch13$PT144-S4-Q15$batch13$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_steps s WHERE s.explanation_id=e.id) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_choice_notes (explanation_id, letter, body) SELECT e.id, v.letter, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES ($batch13$A$batch13$, $batch13$"Supplement" means the same thing throughout.$batch13$), ($batch13$B$batch13$, $batch13$Armstrong doesn't rely on Sullivan's authority. Armstrong rejects it.$batch13$), ($batch13$C$batch13$, $batch13$There's no appeal to emotion.$batch13$), ($batch13$D$batch13$, $batch13$Sullivan's payment is about motive. It doesn't show supplements don't work.$batch13$), ($batch13$E$batch13$, $batch13$The argument never assumes supplements can't be combined with other treatments.$batch13$)) v(letter,body) WHERE q.qid=$batch13$PT144-S4-Q15$batch13$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_choice_notes n WHERE n.explanation_id=e.id AND n.letter=v.letter) ON CONFLICT DO NOTHING;
